import json,time,os,boto3
from botocore.config import Config
DEPLOYMENT='one'
cfg=Config(connect_timeout=3,read_timeout=5,retries={"total_max_attempts":1})
sqs=boto3.client("sqs",config=cfg)
s3=boto3.client("s3",config=cfg)
def exists(key):
    try:
        s3.get_object(Bucket=os.environ["CONTROL_BUCKET"],Key="controls/"+key)["Body"].close()
        return True
    except s3.exceptions.NoSuchKey:
        return False
def handler(event,context):
    marker={"deployment":DEPLOYMENT,"function_version":context.function_version,"invoked_function_arn":context.invoked_function_arn,"request_id":context.aws_request_id,"event":event,"started_at":time.time()}
    sqs.send_message(QueueUrl=os.environ["MARKER_QUEUE"],MessageBody=json.dumps(marker))
    if event["mode"]=="block":
        deadline=time.time()+110
        while time.time()<deadline:
            if exists("release-"+event["case"]):
                marker["released_at"]=time.time()
                return marker
            time.sleep(1)
        raise RuntimeError("owned-blocker-not-released")
    if event["mode"]=="switch" and (DEPLOYMENT=="two" or exists("success-"+event["case"])):
        marker["completed_at"]=time.time()
        return marker
    if event["mode"]=="success":
        return marker
    if event["mode"]=="slowfail": time.sleep(80)
    raise RuntimeError("owned-positive-failure-"+DEPLOYMENT)

